'use strict';
let academyWorker=null,academyFiles=[],academyReport=null;
function showView(view){releaseInputs();for(const [key,id]of [['home','homeView'],['play','matchView'],['academy','academyView']])$(id).hidden=key!==view;for(const [key,id]of [['home','tabHome'],['play','tabPlay'],['academy','tabAcademy']])$(id).classList.toggle('active',key===view);$('tabReplay').classList.remove('active');if(view==='play'){$('gameCanvas').focus();renderer.render();}else if(started&&!paused&&!peerConnected&&!replay)togglePause();}
$('tabHome').onclick=()=>showView('home');$('tabPlay').onclick=()=>showView('play');$('tabAcademy').onclick=$('quickAcademy').onclick=()=>showView('academy');$('tabReplay').onclick=()=>{showView('play');$('replayFile').click();};
function quickPlay(mode){if(typeof closeMatchMenu==='function')closeMatchMenu(false);if(replay)closeReplay();if(peerConnected)disconnect();$('mode').value=mode;showView('play');resetMatch(true);}
$('heroPlay').onclick=$('quickMatch').onclick=()=>quickPlay('bot');$('quickSquad').onclick=()=>quickPlay('4v4');$('quickOnline').onclick=()=>{showView('play');openDialog('networkDialog');};
function setModel(model){FuckballAI.validateModel(model);aiModel=model;FuckballAI.reset(aiModel);$('modelName').textContent=model.name||'Imported model';const metrics=model.source_metrics||{};const accuracy=metrics.direction_accuracy??metrics.dir_accuracy;$('modelAccuracy').textContent=Number.isFinite(accuracy)?(accuracy*100).toFixed(1)+'%':'—';$('modelSamples').textContent=Number(model.training?.train_samples||model.training?.samples||model.training?.train_stats?.samples||0).toLocaleString('en-GB');$('modelDescription').textContent=model.input_columns.length+' features · '+model.b1.length+' neurons · kick F1 '+(Number(metrics.kick_f1)||0).toFixed(2)+' · '+(model.source_kind||'imported');$('exportModel').disabled=false;}
fetch('ai/trained-model.json').then(r=>{if(!r.ok)throw Error('Could not load model');return r.json();}).then(setModel).catch(e=>{$('modelName').textContent='Team AI available';$('modelDescription').textContent=e.message;$('exportModel').disabled=true;});
$('aiMode').onchange=()=>{if($('aiMode').value!=='tactical'&&!aiModel){$('aiMode').value='tactical';notify('Import or train a model first.');}FuckballAI.reset(aiModel);};
$('importModel').onclick=()=>$('modelFile').click();$('modelFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>16*1024*1024)throw Error('Model exceeds 16 MB.');setModel(JSON.parse(await f.text()));notify('Model loaded.');}catch(err){notify(err.message);}e.target.value='';};
$('exportModel').onclick=()=>{if(aiModel)saveBlob(JSON.stringify(aiModel),safeName(aiModel.name)+'.json','application/json');};
$('academyUpload').onclick=()=>$('academyFiles').click();$('academyFiles').onchange=e=>{academyFiles=Array.from(e.target.files||[]);$('datasetSummary').textContent=academyFiles.length+' replays · '+(academyFiles.reduce((s,f)=>s+f.size,0)/1024/1024).toFixed(1)+' MB';$('trainModel').disabled=academyFiles.length<3||!!academyWorker;$('analyzeReplays').disabled=!academyFiles.length||!!academyWorker;};
function taskState(busy){$('cancelTraining').disabled=!busy;$('academyUpload').disabled=busy;$('analyzeReplays').disabled=busy||!academyFiles.length;$('trainModel').disabled=busy||academyFiles.length<3;}
async function startAcademy(train){if(academyWorker)return;try{if(!academyFiles.length)throw Error('Select a replay first.');if(academyFiles.length>20||academyFiles.some(f=>f.size>32*1024*1024)||academyFiles.reduce((s,f)=>s+f.size,0)>128*1024*1024)throw Error('Limit: 20 replays, 32 MB each, 128 MB total.');taskState(true);$('academyState').textContent=train?'TRAINING':'ANALYSIS';$('trainingStatus').textContent='Reading files…';$('trainingProgress').value=0;const worker=new Worker('ai/trainer-worker.js');academyWorker=worker;worker.onerror=e=>finishTask(e.message||'Could not start worker.');worker.onmessage=({data})=>{if(data.type==='progress'){$('trainingProgress').value=data.percent;$('trainingStatus').textContent=data.text;}else if(data.type==='error')finishTask(data.message);else if(data.type==='done'){academyReport=data.report;$('analysisResults').replaceChildren();for(const r of data.report.replays){const el=document.createElement('div');el.className='analysis-row';const title=document.createElement('b');title.textContent=r.name+' · '+r.map;const detail=document.createElement('span');detail.textContent=fmt(r.duration_seconds)+' · '+r.players+' players · '+r.redGoals+'–'+r.blueGoals+' · '+r.kicks+' kicks · '+r.split;el.append(title,detail);$('analysisResults').append(el);}if(data.model){setModel(data.model);$('aiMode').value='tactical';}$('downloadAnalysis').disabled=false;$('trainingProgress').value=100;finishTask(null,data.model?'Candidate model ready.':'Analysis complete.');}};const files=await Promise.all(academyFiles.map(async f=>({name:f.name,bytes:await f.arrayBuffer()})));if(academyWorker===worker)worker.postMessage({files,train},files.map(f=>f.bytes));}catch(e){finishTask(e.message);}}
function finishTask(error,message){academyWorker?.terminate();academyWorker=null;taskState(false);$('academyState').textContent=error?'ERROR':'DONE';$('trainingStatus').textContent=error||message||'Stopped.';}
$('analyzeReplays').onclick=()=>startAcademy(false);$('trainModel').onclick=()=>startAcademy(true);$('cancelTraining').onclick=()=>finishTask(null,'Training stopped. Current model retained.');$('downloadAnalysis').onclick=()=>{if(academyReport)saveBlob(JSON.stringify(academyReport,null,2),'fuckball-replay-analyse.json','application/json');};
showView('home');taskState(false);

$('botDifficulty').value=settings.difficulty||'hard';$('botDifficulty').onchange=()=>{settings.difficulty=$('botDifficulty').value;settings.botLevels={};savePrefs();if(serverLink?.isOwner)serverLink.send({type:'difficulty',difficulty:settings.difficulty,botLevels:{},teamProfile:settings.teamProfile});updateRoster();};
$('watchBots').onclick=()=>quickPlay('watch');
let selfplayWorker=null,selfplayResult=null;
function stopSelfplay(message='Training stopped'){selfplayWorker?.terminate();selfplayWorker=null;$('startSelfplay').disabled=false;$('stopSelfplay').disabled=true;$('selfplayStatus').textContent=message;}
$('startSelfplay').onclick=()=>{if(selfplayWorker)return;try{selfplayWorker=new Worker('ai/selfplay-worker.js');$('startSelfplay').disabled=true;$('stopSelfplay').disabled=false;$('selfplayProgress').value=0;$('selfplayStatus').textContent='Starting 4v4 self-play…';selfplayWorker.onerror=e=>stopSelfplay(e.message||'Training failed');selfplayWorker.onmessage=({data})=>{if(data.type==='progress'){$('selfplayProgress').value=data.percent;$('selfplayStatus').textContent=data.text;}else if(data.type==='error')stopSelfplay(data.message);else if(data.type==='done'){selfplayResult=data.result;if(data.model){setModel(data.model);$('aiMode').value='tactical';}$('useTeamPolicy').disabled=!data.result.promoted;$('exportTeamPolicy').disabled=false;$('selfplayProgress').value=100;stopSelfplay(data.result.promoted?'Training complete. New team tactics passed validation.':'Training complete. Previous team tactics retained.');}};selfplayWorker.postMessage({generations:+$('selfplayGenerations').value,seed:Date.now()>>>0,initial:settings.teamProfile,model:aiModel});}catch(e){stopSelfplay(e.message);}};
$('stopSelfplay').onclick=()=>stopSelfplay();$('useTeamPolicy').onclick=()=>{if(!selfplayResult?.promoted)return;settings.teamProfile=FuckballAI.profile(selfplayResult.profile);savePrefs();if(serverLink?.isOwner)serverLink.send({type:'difficulty',difficulty:settings.difficulty,botLevels:settings.botLevels,teamProfile:settings.teamProfile});notify('Team tactics applied');};$('exportTeamPolicy').onclick=()=>{if(selfplayResult)saveBlob(JSON.stringify(selfplayResult,null,2),'haxlab-selfplay.json','application/json');};

$('refreshTraining').onclick=async()=>{try{const r=await fetch('/api/training');if(!r.ok)throw Error('unavailable');const s=await r.json();$('vpsTrainingStatus').textContent=s.status&&s.status!=='unavailable'?s.status+' · '+(s.matches||0)+' matches · '+(s.cycles||0)+' completed cycles'+(Number.isFinite(s.kickF1)?' · kick F1 '+s.kickF1.toFixed(2):''):'Open the VPS game to view server training.';}catch{$('vpsTrainingStatus').textContent='Open the VPS game to view server training.';}};
